<template><header class="page-head"><div><div class="eyebrow">{{PAGE_LABELS[3]}}</div><h1>判读结果</h1></div><StatusBadge v-if="state.data" :status="state.data.status"/></header><div v-if="state.error" class="error-box">{{state.error}}</div><div v-if="!state.data" class="empty">正在读取结果…</div><div v-else class="content-grid"><section><span class="method-tag">{{state.data.result.method}}</span><h2 class="run-headline" style="margin-top:18px">{{state.data.result.headline}}</h2><p class="muted" style="max-width:800px;line-height:1.8">{{state.data.result.narrative}}</p></section><div class="stat-row"><StatTile v-for="metric in state.data.result.metrics" :key="metric.label" :label="metric.label" :value="metric.value" :unit="metric.unit" :tone="metric.tone"/></div><div class="content-grid grid-main"><AppPanel title="效应与分组"><BarChart :series="state.data.result.series"/></AppPanel><AppPanel title="运行证据"><div class="content-grid"><div><span class="eyebrow">checksum</span><div class="mono">{{checksum(state.data.checksum)}}</div></div><div><span class="eyebrow">created</span><p>{{dateTime(state.data.created_at)}}</p></div><div><span class="eyebrow">run id</span><div class="mono">{{state.data.id}}</div></div></div></AppPanel></div><AppPanel title="算法限制"><p class="caveat">{{state.data.result.caveat}}</p></AppPanel><AppPanel title="结果表"><DataTable :rows="state.data.result.table"/></AppPanel></div></template>
<script setup lang="ts">import { useRoute } from "vue-router"; import { getRun } from "../api/runs"; import AppPanel from "../components/common/AppPanel.vue"; import BarChart from "../components/common/BarChart.vue"; import DataTable from "../components/common/DataTable.vue"; import StatTile from "../components/common/StatTile.vue"; import StatusBadge from "../components/common/StatusBadge.vue"; import { PAGE_LABELS } from "../constants/domain"; import { useAsync } from "../hooks/useAsync"; import { checksum, dateTime } from "../utils/format"; const route=useRoute(); const state=useAsync(()=>getRun(String(route.params.runId)));</script>
